-- 아트록스 챔피언 위키: MOBAFire (2662자)
UPDATE wiki_docs
SET general = '# 탑 라인 실전 운용

> **한눈에 보기** — `Q` 끝을 맞힐 거리를 만든다 · `E`는 피해보다 위치 보정에 쓴다 · 궁극기의 회복 증폭은 적중해야 의미가 있다

[[분류:탑]] [[분류:딜탱]]

## 첫 `Q`는 피해보다 다음 칼날의 자리를 만든다

**`다르킨의 검(Q)`은 세 번의 범위와 핵심 타격 지점이 서로 다르다.** 첫 칼날의 바깥쪽으로 상대를 띄운 뒤 `지옥사슬(W)`을 걸면 다음 칼날을 피할 공간이 줄어든다.[* [아트록스 원챔러의 글](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=145316&vtype=pc)] 첫 타가 빗나갔다면 남은 횟수를 무조건 소비하지 않는다. 웨이브를 함께 긁어 라인을 밀어 버릴지, 재사용 대기시간을 앞당길지 먼저 고른다.

## `E`는 칼날이 내려오는 순간에 짧게 보정한다

**`파멸의 돌진(E)`을 먼저 써서 거리를 좁히면 상대는 `Q`의 방향을 읽기 쉽다.** `Q`를 누른 뒤 상대가 옆으로 피하는 움직임에 맞춰 짧게 보정하면 핵심부 적중률이 높아진다. 반대로 상대의 강한 진입기가 남아 있다면 `E`를 공격에 모두 쓰지 않고 첫 반격을 피할 여지를 남긴다.

## 사슬은 도망칠 길이 좁을 때 건다

**`지옥사슬(W)`은 맞히는 순간보다 끌려오는 순간에 가치가 생긴다.**[* [메타에 따라 바뀌는 아트록스 공략](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=142004&vtype=pc)] 상대 뒤에 벽이나 미니언이 있어 옆으로 빠질 길이 줄었을 때 사용하고, 사슬 중앙으로 이동할 상대에게 두 번째 `Q`를 겹친다. 넓은 공간에서 빗나가면 억지로 추격하지 않고 다음 웨이브까지 기다린다.

## 궁극기는 첫 적중 직전에 켠다

**`세계의 종결자(R)`의 이동 속도와 회복 증폭은 실제로 챔피언을 맞힐 때 힘이 난다.** 너무 일찍 켜고 걸어가면 지속시간만 줄어든다. 첫 `Q`나 사슬이 닿을 구도가 만들어진 뒤 켜고, 처치 관여로 지속시간이 늘어날 수 있는 교전에서는 체력이 낮은 대상부터 무리하게 쫓기보다 다음 핵심 타격이 닿는 대상을 고른다.

## 커뮤니티에서 반복되는 실전 기준

아트록스의 짤교는 첫 `Q` 끝을 맞힌 뒤 무조건 3타까지 쓰는 콤보가 아니다. 첫 타로 상대 무빙을 보고, `W`가 걸리거나 퇴로가 좁아졌을 때만 두 번째와 세 번째 칼날을 이어야 스킬이 전부 빠진 채 역으로 맞는 시간을 줄일 수 있다.[* [MOBAFire 아트록스 매치업 가이드](https://www.mobafire.com/league-of-legends/build/aatrox-guide-with-matchups-updated-every-patch-584077)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`E` 한 번을 딜 욕심에 먼저 써 버리면 다음 `Q`를 보정할 수 없고 갱에도 취약해진다. 상대 이동기가 빠졌을 때는 공격용으로 써도 되지만, 이동기가 남아 있거나 정글 위치가 안 보이면 `Q`가 내려오는 순간의 미세 조정용으로 아끼는 편이 안정적이다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

라인을 계속 밀면 긴 사거리의 첫 `Q`로 압박하기는 쉽지만, 상대가 포탑 앞에서 버티면 `W`가 당겨질 공간이 사라진다. 킬각을 만들고 싶다면 원거리 미니언만 정리해 천천히 밀거나, 라인을 내 쪽으로 한 번 당겨 상대가 길게 걸어 나오게 만든다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 궁을 켜고 가장 멀리 있는 딜러만 쫓기보다, 당장 `Q` 끝을 맞힐 수 있는 앞라인부터 때려 회복과 궁 지속시간을 확보한다. 첫 진입에서 핵심부를 못 맞혔다면 잠깐 빠져 다음 `Q` 각을 다시 잡는 것이 무작정 평타로 비비는 것보다 낫다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **아트록스의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- 첫 `Q`가 빗나가면 3타까지 억지로 쓰지 않기
- `E`를 진입과 도주 중 어디에 쓸지 먼저 정하기
- 상대 이동기가 빠진 뒤 `W` 걸기
- 라인이 너무 밀렸다면 다음 웨이브에서 당길 준비하기
