> **한눈에 보기** — `Q` 도끼날과 자루를 구분한다 · 출혈 다섯 중첩 전에는 퇴로를 남긴다 · 라인을 얼릴 때는 광역기를 아낀다

[[분류:탑]] [[분류:딜탱]]

## 도끼날을 맞힐 공간부터 확보한다

**`학살(Q)`은 바깥 도끼날을 맞혀야 큰 피해와 회복을 함께 얻는다.**[* [다리우스 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=98)] 상대가 안으로 파고들면 자루에 맞으므로 `마비의 일격(W)` 둔화나 `포획(E)` 뒤에 반 걸음 물러나 끝 거리를 맞춘다. 체력이 낮을수록 여러 챔피언을 긁겠다고 중앙으로 들어가기보다 도끼날이 확실한 한 명을 고른다.

## 출혈 중첩은 한 번에 완성하려 하지 않는다

**기본 공격과 기술 사이를 끊지 않아야 다섯 중첩의 압박이 생긴다.** 상대의 이동기가 남았는데 `E`부터 쓰면 마지막 중첩 전에 거리가 벌어진다. 먼저 걸어서 기본 공격과 `W`를 묻히고, 도주가 시작될 때 끌어당기는 편이 긴 교환을 이어 가기 쉽다.

## `Q`를 웨이브에 쓰기 전에 라인 위치를 본다

**막타 견제로 `Q`를 반복하면 원치 않게 라인이 밀려 상대 포탑 앞에 얼 수 있다.**[* [D3 오열다리 공략](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=133490)] 확실한 교환이 아니라면 기본 공격으로 미니언을 정리하고, 상대가 도끼날과 막타를 동시에 내줄 때만 넓게 휘두른다. 긴 라인에서 싸우고 싶다면 강가 쪽 정보를 먼저 확인한다.

## 궁극기는 중첩과 다음 대상을 함께 본다

**`녹서스의 단두대(R)`는 출혈이 쌓일수록 강해지고 처치하면 다시 쓸 기회가 생긴다.** 한 명을 너무 일찍 찍어 처치에 실패하면 가장 강한 연쇄가 끊긴다. 현재 대상의 중첩 수와 남은 체력을 확인하고, 처치 뒤 바로 닿을 다음 적이 있는지도 보고 뛰어든다.

## 커뮤니티에서 반복되는 실전 기준

다리우스의 라인전은 한 번 끌었다고 바로 킬이 나는 챔피언이 아니라, 상대가 빠질 거리를 계산해 출혈 5스택까지 이어 가는 챔피언이다. `E`를 먼저 쓰기보다 평타와 `W`로 도망 방향을 제한한 뒤 마지막 도주기를 끊는 용도로 끌어야 맞딜이 끊기지 않는다.[* [MOBAFire 다리우스 심화 가이드](https://www.mobafire.com/league-of-legends/build/darius-in-depth-build-every-matchup-explained-642445)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`Q` 도끼날을 못 맞히면 회복과 출혈이 같이 사라져 긴 싸움의 힘이 크게 떨어진다. 상대가 안쪽으로 파고들 수 있는 챔피언이면 `E`로 거리를 벌리거나 한 발 옆으로 비켜 외곽을 맞히고, 실패했다면 5스택만 보고 무리하지 않는다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

선푸시를 잡아도 라인이 상대 포탑 앞에 고정되면 다리우스가 가장 원하는 긴 추격 구간이 사라진다. 첫 웨이브부터 무작정 밀기보다 근접 미니언 우위를 만들고 천천히 쌓아 박은 뒤, 튕겨 오는 라인을 내 포탑 쪽에 묶어 킬각을 만든다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 앞라인에 출혈을 쌓다가 5스택이 완성된 순간 다른 대상에게 평타나 `Q`를 묻혀 전투를 넓힌다. 궁 초기화만 보고 체력이 먼 대상을 쫓기보다, 확실히 처형 가능한 대상부터 잘라 패시브를 켜는 것이 핵심이다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **다리우스의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- `E`를 먼저 쓰기 전에 상대 도주기 확인하기
- `Q` 안쪽이 아니라 도끼날 맞히기
- 출혈 숫자만 보고 불리한 맞딜을 계속하지 않기
- 라인을 당겨 긴 추격로 만들기
