[[분류:탑]] [[분류:딜탱]]

## 회복 구간을 웨이브와 맞춘다

**가렌의 유지력은 상대 챔피언에게 맞지 않는 시간을 확보할 때 돌아온다.**[* [새 시즌 가렌 연구](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=148076)] 체력이 빠졌다면 막타 하나를 위해 견제 범위로 다시 들어가기보다 미니언이 내 쪽으로 오게 두고 잠시 거리를 둔다. 회복이 시작된 뒤에야 다음 교환을 열어야 짧은 교환을 반복하는 강점이 살아난다.

## `Q`는 접근 버튼이자 둔화 해제다

**`결정타(Q)`를 상대가 보이는 즉시 누르지 말고, 먼저 걸려 오는 둔화를 지울 순간을 기다린다.** 침묵 뒤 `심판(E)`을 이어야 상대의 반격 기술을 늦출 수 있다. 접근할 수 없는 거리에서 이동 속도만 소비했다면 웨이브를 밀겠다고 깊이 따라가지 않는다.

## `W`의 첫 순간을 큰 공격에 겹친다

**`용기(W)`는 사용 직후의 보호막과 강인함이 가장 급한 피해와 제어를 넘기는 구간이다.**[* [진짜 가렌 공략](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=142970&vtype=pc)] 상대의 약한 견제에 미리 쓰지 않고, 기절이나 강한 단일 기술이 닿기 직전에 켠다. `W`가 없을 때는 평소와 같은 거리로 들어가지 않는다.

## `E`가 끝난 뒤의 거리를 계산한다

**`심판(E)`은 한 대상을 가까이 두고 끝까지 맞힐 때 압박이 커진다.** 회전 중 상대 포탑 쪽으로 깊어지면 끝난 뒤 빠질 기술이 없다. `Q` 침묵 동안 필요한 만큼만 따라가고, 처형 가능한 체력이 아니라면 상대의 이동기가 돌아오기 전에 회전을 끊고 나온다.

## 커뮤니티에서 반복되는 실전 기준

가렌의 기본 짤교는 `Q`로 들어가 `E`를 전부 돌리는 고정 콤보가 아니다. 상대가 반격할 핵심기를 쓰기 전에 침묵으로 끊고, `E`가 끝날 때까지 붙을 수 있는 거리인지 확인한 뒤 진입해야 빠지는 길에서 손해를 보지 않는다.[* [MOBAFire 가렌 라인전 가이드](https://www.mobafire.com/league-of-legends/build/garen-in-depth-1v9-build-s13-patch-13-4-complete-matchup-top-mid-and-also-lots-of-tips-for-laning-phase-620122)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W`는 보호막보다 짧은 강인함 구간을 맞추는 것이 중요하다. 상대의 기절이나 띄우기 모션이 보일 때 눌러 CC 시간을 줄이고, 큰 피해가 뒤따르는 스킬까지 함께 받아 내면 같은 체력으로도 다음 짤교를 먼저 열 수 있다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

패시브 회복을 살리려면 라인을 무조건 밀며 견제를 맞는 것보다 잠깐 시야 밖으로 빠져 피해를 안 받는 시간이 필요하다. 체력이 빠졌다면 근접 미니언 몇 개를 포기하더라도 수풀과 포탑 뒤에서 회복을 켜고 다음 웨이브에 다시 압박한다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서 가렌은 정면으로 다섯 명을 뚫는 탱커가 아니다. 옆각에서 딜러에게 침묵을 넣거나, 아군 딜러에게 붙는 브루저를 `Q`와 `E`로 잘라 체력을 처형선까지 낮추는 역할이 더 안정적이다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **가렌의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

