> **한눈에 보기** — 분노 50을 어떤 기술에 쓸지 먼저 정한다 · 첫 `E`는 대상을 맞혀야 두 번째가 열린다 · 궁극기로 다음 강화 기술을 당긴다

[[분류:탑]] [[분류:딜탱]]

## 분노는 교환 전에 용도를 정한다

**레넥톤의 같은 기술도 분노 50을 넘으면 역할이 달라진다.**[* [D3 탑 레넥톤 공략](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=132728&vtype=pc)] 체력을 회복하며 여러 대상을 긁어야 하면 강화 `양떼 도륙(Q)`, 보호막을 깨고 오래 묶어야 하면 강화 `무자비한 포식자(W)`, 방어력을 낮춰 긴 싸움을 열어야 하면 두 번째 `자르고 토막내기(E)`에 쓴다. 교환 도중 우연히 먼저 눌린 기술에 분노를 쓰지 않는다.

## 첫 돌진은 미니언을 통과해 쓴다

**`자르기(E)`가 적을 맞혀야 짧은 시간 안에 `토막내기(E)`를 다시 쓸 수 있다.**[* [레넥톤 500판 공략](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=138688)] 상대에게 바로 닿지 않아도 앞 미니언을 통과해 두 번째 돌진을 열고, `W`와 `Q` 교환 뒤 아군 쪽으로 빠지는 경로를 남긴다. 두 번을 모두 진입에 쓰면 상대 정글이 보이지 않을 때 퇴로가 없다.

## 짧은 교환은 기절 시간 안에 끝낸다

**`W`로 묶은 동안 기본 공격을 더 욕심내기보다 `Q`까지 넣고 두 번째 `E`로 나온다.** 상대의 반격이 시작된 뒤 빠지면 레넥톤의 짧은 폭발력보다 긴 재사용 대기시간이 드러난다. 강화 `W`가 필요하다면 분노가 차기 전부터 거리를 좁히지 않는다.

## 궁극기는 체력보다 분노 흐름을 본다

**`강신(R)`은 추가 체력과 함께 즉시·지속적으로 분노를 공급한다.** 체력이 거의 사라진 뒤 생존용으로만 누르면 강화 기술을 쓸 시간이 없다. 교환이 길어질 것이 확정된 순간에 켜서 첫 강화 기술을 당기고, 주변 피해를 넣으려 상대 포탑 쪽으로 무리하게 붙지는 않는다.

## 커뮤니티에서 반복되는 실전 기준

레넥톤의 교환은 분노 50을 어느 스킬에 쓰느냐가 전부다. 짧은 확정 딜교는 강화 `W`, 여러 명과 미니언을 함께 긁어 회복할 때는 강화 `Q`, 탱커를 길게 칠 때는 두 번째 `E` 강화가 좋으므로 싸움 전에 목적을 정한다.[* [MOBAFire 레넥톤 탑 가이드](https://www.mobafire.com/league-of-legends/build/top-lane-renekton-208385)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

첫 `E`로 들어간 뒤 바로 두 번째 `E`를 쓰면 상대는 편하게 빠졌다가 다시 들어올 수 있다. `W`와 평타, `Q`를 넣는 동안 상대 이동을 보고 두 번째 돌진을 추격 또는 탈출 중 하나로 남겨야 정글 개입에도 버틸 수 있다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

분노를 채우려고 웨이브를 계속 긁으면 자연스럽게 라인이 밀린다. 큰 웨이브를 박을 때는 강하게 압박하되, 다음 라인이 튕겨 올 때는 스킬로 전부 지우지 말고 내 쪽에서 받아 긴 추격 거리를 만든다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

중후반에는 초반처럼 아무 앞라인과 오래 맞딜하기보다 측면에서 딜러에게 강화 `W`를 넣거나, 아군 딜러를 무는 적을 끊는다. 궁은 체력이 다 빠진 뒤가 아니라 진입 직전에 켜 분노 수급과 추가 체력을 모두 활용한다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **레넥톤의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- 싸움 전에 강화할 스킬 정하기
- 두 번째 `E`를 바로 쓰지 않기
- 강화 `Q`는 챔피언과 미니언을 함께 맞히기
- 분노 때문에 라인을 과하게 밀지 않기
