> **한눈에 보기** — 양쪽에 적을 둬 `E` 기절을 만든다 · 투지가 찼을 때 `W` 중심선을 고정한다 · 궁극기의 착지 방향을 먼저 고른다

[[분류:탑]] [[분류:딜탱]]

## 오른손까지 맞힌 뒤 `Q`로 다시 잇는다

**세트의 기본 공격은 왼손과 빠른 오른손이 한 묶음이다.** 두 번째 주먹까지 닿는 거리에서 `주먹다짐(Q)`으로 공격 흐름을 다시 시작하면 짧은 시간에 네 번의 타격을 연결할 수 있다.[* [세트 사용법 강의](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=147651&vtype=pc)] 상대가 첫 주먹 뒤 바로 빠질 수 있다면 `Q`를 먼저 켜 이동 속도로 거리를 좁힌다.

## `E` 기절은 미니언 배치가 만든다

**`안면 강타(E)`는 양쪽에서 적을 끌어야 기절하고, 한쪽에만 있으면 둔화에 그친다.** 상대 챔피언 반대편에 적 미니언을 두고 서면 확정성이 높아진다. 웨이브를 모두 정리한 뒤에는 같은 버튼이 약해지므로, 막타를 치기 전에 교환 위치부터 잡는다.

## 투지가 많아도 중심선이 아니면 기다린다

**`강펀치(W)`는 저장한 투지가 클수록 보호막과 중심선 피해가 커진다.**[* [세트의 모든 것을 담은 사용법](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=147651&vtype=pc)] 체력이 낮아졌다는 이유만으로 즉시 쓰면 상대가 옆으로 빠진다. `E` 기절이나 둔화로 중심선을 고정할 수 있을 때 연결하고, 그 각이 없다면 보호막으로 다음 피해를 넘기는 데 집중한다.

## 궁극기는 잡을 대상보다 떨어질 곳을 본다

**`대미 장식(R)`은 붙잡은 적 뒤편으로 이동해 함께 착지한다.** 상대 앞라인을 아군 쪽으로 넘길지, 그 몸을 이용해 뒤쪽 여러 명에게 충돌 피해를 줄지 먼저 정한다. 착지 뒤 혼자 고립되는 방향이라면 잡을 수 있다는 이유만으로 사용하지 않는다.

## 커뮤니티에서 반복되는 실전 기준

세트는 좌우 펀치와 `Q` 평캔을 묶을 때 짧은 시간에 평타 네 대를 넣을 수 있다. 무작정 `Q`를 켜고 달리기보다 평타 두 대가 닿는 거리에서 시작해 `Q`로 모션을 끊어야 이동 속도와 강화 평타를 모두 낭비하지 않는다.[* [MOBAFire 챌린저 세트 가이드](https://www.mobafire.com/league-of-legends/build/26-18-autolykuss-challenger-sett-guide-594869)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W`는 투지가 많이 찼다는 이유만으로 바로 쓰면 중심 고정 피해를 쉽게 피한다. `E`로 양쪽 유닛을 잡아 기절시키거나 상대 이동기가 빠진 뒤 사용하고, 투지가 빠르게 줄기 시작하기 전에 발사할 타이밍을 익힌다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

`E` 기절을 만들려면 챔피언 반대편에 미니언이 있어야 하므로 웨이브 위치가 곧 교환 각이다. 라인을 전부 밀어 미니언이 사라지면 단순 둔화만 남으니, 킬각이 필요할 때는 적 미니언 한두 마리를 일부러 남겨 잡아당길 축으로 쓴다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 체력이 많은 앞라인을 `R`로 잡아 적 딜러 쪽에 꽂는 각과, 아군 딜러를 무는 적을 뒤로 넘겨 떼어 내는 각을 구분한다. 대박 궁만 찾다가 걸어 들어가 맞기보다 측면 시야에서 진입 거리를 줄이는 것이 중요하다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **세트의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- 평타 두 대 뒤 `Q`로 평캔하기
- `W` 중심을 맞힐 고정 수단 남기기
- `E` 반대편 미니언 위치 확인하기
- 투지 감소 전에 `W` 쓰기
