> **한눈에 보기** — `Q` 사이마다 기본 공격을 둔다 · 세 번째 `Q`의 밀치기를 따로 계산한다 · `E`를 쓰고 난 뒤의 퇴로를 남긴다

[[분류:탑]] [[분류:딜탱]]

## 세 번의 `Q`를 한꺼번에 소비하지 않는다

**`부러진 날개(Q)`는 돌진과 공격을 세 번 나눠 쓰며 마지막 타격이 적을 밀쳐 낸다.** 첫 `Q`로 거리를 좁힌 뒤 기본 공격, 다음 `Q` 뒤 다시 기본 공격을 섞어야 기술 사이의 시간을 피해로 바꿀 수 있다.[* [탑 리븐 라인전 가이드](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=115049&vtype=pc)] 상대가 빠졌다면 세 번째 `Q`는 쫓기보다 안전하게 나오는 데 쓴다.

## 기절과 밀치기의 순서를 고른다

**`기 폭발(W)`은 아주 가까운 적을 즉시 묶고, 세 번째 `Q`는 착지 지점에서 적을 밀친다.** 두 제어를 겹쳐 낭비하지 않고 상대의 이동기를 한 번 본 뒤 두 번째를 잇는다. 짧은 교환에서는 `W` 동안 한 대를 더 치고 `Q`로 빠지는 식으로 상대의 반격 시간을 줄인다.

## `E` 보호막은 들어갈 때보다 나올 때 값질 수 있다

**`용맹(E)`은 짧게 이동하며 피해를 흡수한다.**[* [리븐 기초 공략](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=140432&vtype=pc)] 먼저 접근에 쓰면 교환 뒤 돌아올 수단이 줄어든다. 상대의 핵심 공격을 막으면서 옆으로 비켜 갈지, 콤보가 끝난 뒤 미니언 뒤로 빠질지 미리 정하고 사용한다.

## 궁극기의 두 번째 사용은 체력과 거리를 함께 본다

**`추방자의 검(R)`을 켜면 공격력과 사거리가 늘고, 한 번의 `바람 가르기`를 사용할 수 있다.** 상대 체력이 낮을수록 마무리 가치가 커지지만 멀리서 성급히 던지면 피하기 쉽다. `W`나 세 번째 `Q`로 움직임을 제한한 뒤 사용하고, 첫 활성화가 남아 있는 동안 기본 공격 사거리 이점도 챙긴다.

## 커뮤니티에서 반복되는 실전 기준

리븐의 딜교는 빠른 콤보를 외우는 것보다 `Q`와 평타를 섞어 패시브를 버리지 않는 데서 시작한다. 짧게 칠 때는 `E`로 피해를 받고 `W`로 묶은 뒤 평타와 `Q` 한두 번만 쓰고, 남은 `Q`는 빠지는 거리로 남긴다.[* [MOBAFire 리븐 탑·미드 가이드](https://www.mobafire.com/league-of-legends/build/26-18-molinas-riven-top-mid-guide-619423)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`E` 보호막을 당황해서 먼저 쓰면 상대 핵심 피해를 막지 못하고 다음 진입까지 스킬쿨만 빈다. 상대 모션을 보고 받는 피해에 맞추거나 `E-W`로 안전하게 붙는 식으로 목적을 정하고, 모든 이동기를 진입에 소모하지 않는다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

리븐은 스킬로 웨이브를 빨리 지울 수 있지만 `Q`를 미니언에 모두 쓰면 상대가 바로 걸어올 때 대응할 수 없다. 선푸시가 필요한 타이밍과 교환이 필요한 타이밍을 나눠, 최소 한 번의 `Q` 또는 `E`는 갱 회피와 거리 조절에 남긴다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 정면에서 스킬을 다 쓰며 들어가기보다 측면에서 `Q`를 미리 굴려 세 번째 에어본 타이밍을 맞춘다. 궁 2타는 체력이 낮은 대상을 마무리하는 용도지만, 여러 명을 맞힐 수 있다면 처형 욕심보다 광역 피해와 진형 붕괴를 우선한다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **리븐의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- `Q` 사이에 평타 넣어 패시브 쓰기
- 남은 `Q`를 진입과 이탈 중 어디에 쓸지 정하기
- `E`를 상대 핵심 피해에 맞추기
- 웨이브 정리에 이동기를 전부 쓰지 않기
