UPDATE wiki_docs
SET general = '# 탑 라인 실전 운용

> **한눈에 보기** — 낮은 체력 미니언으로 왕복 경로를 만든다 · 패시브 중첩이 낮으면 싸우지 않는다 · `W`로 큰 물리 피해를 받아낸다

[[분류:탑]] [[분류:딜탱]]

## 낮은 체력 미니언을 진입과 복귀로 나눈다

**`칼날 쇄도(Q)`로 처치할 수 있는 미니언은 이렐리아의 이동 경로다.**[* [이렐리아 공략 원문](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=145057)] 상대 가까이 있는 미니언만 준비하면 들어간 뒤 나올 길이 없다. 아군 쪽에 돌아올 미니언 하나를 남기고, `Q` 한 번에 죽을 체력인지 확인한 뒤 교환을 연다.

## 패시브 중첩이 준비된 웨이브에서 싸운다

**기술을 맞힐 때 쌓이는 중첩은 최대일 때 기본 공격의 위력을 크게 높인다.**[* [이렐리아 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=22)] 중첩이 낮은 채 챔피언에게 `Q`부터 쓰면 초기화도 받지 못하고 긴 탑 라인 가운데에 남는다. 미니언을 정리하며 중첩을 만들고 표식이 생겼을 때만 챔피언을 경로에 넣는다.

## `E`는 두 칼날 사이의 선으로 맞힌다

**`쌍검협무(E)`는 두 칼날이 서로를 향해 날아가는 선 위의 적을 기절시키고 표식을 남긴다.** 첫 칼날을 상대가 보는 정면에 두면 두 번째 위치를 읽기 쉽다. 내 발밑이나 이동 경로 뒤에 첫 칼날을 숨기고, 상대가 막타 동작에 들어갈 때 선을 완성한다.

## `W`가 줄이지 못하는 피해까지 버티지 않는다

**`저항의 춤(W)`은 충전 중 물리 피해를 줄이지만 제자리에서 시간을 쓴다.** 상대의 강한 물리 공격이 예고됐을 때 받아내고, 끝나는 방향으로 피해를 돌려준다. 장판이나 마법 피해까지 모두 견디는 기술로 생각하지 말고, 위험이 겹치면 충전을 짧게 끝내 위치부터 바꾼다.

## 커뮤니티에서 반복되는 실전 기준

이렐리아는 체력이 낮은 미니언을 미리 만들어 `Q` 리셋 길을 깔아 두는 것이 라인전의 절반이다. 상대에게 바로 돌진하기보다 근접 미니언과 원거리 미니언을 징검다리로 써서 패시브를 채운 뒤, 표식이 생겼을 때만 두 번째 `Q`로 추격한다.[* [MOBAFire 이렐리아 탑·미드 가이드](https://www.mobafire.com/league-of-legends/build/patch-26-09-definitive-irelia-top-mid-guide-632085)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W`는 모든 피해를 지우는 무적기가 아니라 물리 피해를 크게 줄이며 다음 미니언 막타를 만드는 기술이다. 상대의 큰 물리 피해를 받아 내면서 웨이브 체력을 조절하고, 마법 피해나 CC를 막을 수 있다고 착각해 채널링을 고집하지 않는다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

라인을 빨리 밀면 `Q` 탈출용 미니언이 사라져 오히려 정글에게 잡히기 쉽다. 싸움을 열기 전에는 내 뒤와 옆에 체력이 낮은 미니언을 하나씩 남겨 두고, 킬각이 아니면 적 챔피언에게 마지막 `Q`를 써서 복귀 경로를 끊지 않는다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 앞에서부터 평타만 치기보다 `R`로 여러 명에게 표식을 묻히고 `Q` 리셋을 이용해 위험 지역을 짧게 통과한다. 딜러에게 들어가더라도 돌아올 표식이나 미니언이 없다면 한 번의 진입으로 끝나므로, 다음 착지 지점을 먼저 본다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **이렐리아의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- 싸움 전 미니언 체력 미리 깎아 두기
- 패시브 중첩이 없을 때 억지 맞딜하지 않기
- `W`는 물리 피해 대응에 쓰기
- 마지막 `Q` 전에 돌아올 미니언 보기
