> **한눈에 보기** — 급소가 안전한 방향일 때만 찌른다 · `W`는 상대의 제어에 맞춘다 · 궁극기는 다음 급소로 갈 동선을 먼저 본다

[[분류:탑]] [[분류:딜탱]]

## 급소 하나보다 찌른 뒤의 위치가 중요하다

**`찌르기(Q)`는 짧게 돌진해 가까운 대상과 급소를 우선 공격한다.**[* [피오라 3분 공략](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=119841&vtype=pc)] 상대 뒤쪽 급소를 치려고 포탑 쪽으로 깊게 들어가면 재사용 대기시간이 줄어도 돌아올 길이 위험하다. 내 쪽이나 옆쪽 급소를 기다리고, 찌른 뒤 수풀이나 미니언 뒤로 빠질 각을 남긴다.

## `W`는 가장 큰 제어 하나에 맞춘다

**`응수(W)`는 짧은 시간 모든 피해와 이동 불가 효과를 막고, 제어를 막으면 상대를 기절시킨다.** 상대가 여러 기술을 연달아 쓸 수 있다면 첫 견제에 반사적으로 누르지 않는다. 확실한 기절이나 폭발 피해가 시작되는 동작을 정해 두고, 응수 방향도 상대가 옆으로 피할 곳에 맞춘다.

## 기본 공격의 리듬으로 급소 사이를 이동한다

**`대가의 검술(E)` 첫 공격은 둔화하고 두 번째는 더 강하게 적중한다.** `Q`로 급소를 친 뒤 첫 공격으로 상대의 이동을 늦추고 다음 급소 쪽으로 걸어간다. 모든 버튼을 같은 자리에서 소비하기보다 둔화 시간에 몸을 옮겨야 긴 교환이 이어진다.

## 궁극기는 네 방향을 도는 순서를 정하고 건다

**`대결투(R)`은 네 급소를 모두 치거나 급소를 친 대상이 쓰러지면 회복 지대를 만든다.**[* [시즌10 피오라 상대법 공략](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=146186&vtype=pc)] 벽에 붙은 대상을 골라 마지막 급소가 막히지 않는지 보고, 가까운 급소부터 시계 방향이나 반대 방향으로 이어 갈 순서를 정한다. 한 급소를 치고 상대의 제어가 남았다면 속도보다 `W` 타이밍을 우선한다.

## 커뮤니티에서 반복되는 실전 기준

피오라의 짤교는 급소를 보자마자 `Q`로 들어가는 것이 아니라, 맞힌 뒤 빠질 이동 속도와 상대 반격기를 함께 계산해야 한다. 불리한 방향의 급소는 시야 밖으로 잠깐 빠져 위치를 바꾸고, 좋은 급소가 나왔을 때만 짧게 찌른다.[* [MOBAFire 랭크 1 피오라 가이드](https://www.mobafire.com/league-of-legends/build/rank-1-fiora-guide-by-draco-26-03-651248)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W`는 기절을 막는 기술로만 생각하면 사용 타이밍이 너무 뻔해진다. 큰 피해 한 번이나 공격 속도 의존 챔피언의 핵심 구간을 막는 용도로도 가치가 크며, 맞히지 못한 `W`는 긴 스킬쿨 동안 킬각을 통째로 내준다는 점을 감수해야 한다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

피오라는 초반 광역 정리가 약해 라인을 박는 속도가 느릴 수 있다. 킬을 냈다고 무조건 끝까지 밀기보다 다음 웨이브 위치를 보고 귀환하고, 사이드를 길게 운영할 때는 상대 합류 전에 포탑과 웨이브 중 무엇을 챙길지 먼저 정한다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 앞라인을 무시하고 딜러만 찾다가 CC에 묶이는 실수가 많다. 바로 터뜨릴 수 있는 대상에게 궁을 걸어 회복 장판을 빨리 만들거나, 측면에서 한 명을 묶어 숫자 우위를 만드는 식으로 사이드 강점을 전투에 연결한다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **피오라의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

