**`반격(E)`은 짧은 시간 기본 공격을 회피하고, 끝날 때 주변 적을 기절시킨다.**[* [잭스 챔피언별 상대법](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=143406)] 상대가 기본 공격을 시작한 뒤 켜서 피해를 흘리고, 너무 멀리 달아나기 전에 다시 눌러 기절을 확정한다. 기술 피해만 쓰는 상대에게는 회피보다 기절 거리 확보가 목적이다.

## `Q`는 마지막까지 남길 수 있는 이동기다

**`도약 공격(Q)`은 적 챔피언뿐 아니라 유닛을 향해 이동할 수 있다.** 먼저 걸어서 `W` 강화 공격을 넣고 상대가 빠질 때 따라가거나, 교환이 끝난 뒤 아군 미니언으로 빠지는 편이 안전하다. 처음부터 도약하면 상대의 이동기를 쫓을 수 없고 정글 개입에도 취약해진다.

## 궁극기의 방어력은 여러 명이 닿을 때 키운다

**`R`을 사용하면 주변에 피해를 주고 잠시 방어력과 마법 저항력을 얻는다.**[* [잭스 공략과 스킬 설명](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=143406)] 혼자 있는 약한 대상을 잡는 데 성급히 쓰기보다 둘 이상에게 둘러싸이거나 큰 피해가 들어오기 직전에 사용한다. 방어 시간이 끝나기 전에 목적 대상을 정하고 계속 공격해 기본 지속 효과의 흐름을 잇는다.

## 커뮤니티에서 반복되는 실전 기준

잭스의 짧은 딜교는 미니언에 평타 두 번을 쌓고 `Q-평-W`로 궁 3타를 터뜨리는 흐름이 강하다. 다만 `Q`를 먼저 쓰면 빠질 수단이 없어지므로 상대 반격이 강한 구도에서는 걸어서 접근하거나 아군 미니언을 탈출 발판으로 남긴다.[* [MOBAFire 잭스 심화 가이드](https://www.mobafire.com/league-of-legends/build/26-18-thisispatriks-in-depth-jax-guide-503356)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`E` 반격은 평타를 막는 동안 최대한 오래 들고 있어야 상대가 공격을 멈추거나 이동기를 먼저 쓰게 만든다. 기절을 바로 터뜨리는 습관을 버리고, 상대 핵심 평타 강화가 소모됐는지와 빠질 방향을 본 뒤 재사용한다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

패시브 공속을 쌓으려고 웨이브를 계속 치면 라인이 밀리고 갱에 노출된다. 교환 직전 필요한 만큼만 중첩을 만들고, `Q`로 빠질 아군 미니언이나 와드가 없는 깊은 위치에서는 선푸시 욕심을 줄인다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 `E`를 켜고 무조건 딜러에게 점프하기보다 앞라인의 평타를 무력화하며 공간을 먹는 선택도 좋다. 상대 딜러의 생존기가 빠졌거나 아군 진입이 맞춰질 때 `Q`로 넘어가야 혼자 들어가 녹는 일을 줄일 수 있다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **잭스의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- 교환 전 평타 중첩 만들기
- `Q`를 진입에 쓰면 탈출 경로 확인하기
- `E`를 바로 터뜨리지 않기
- 아군 미니언을 도약 발판으로 남기기
- 한타 진입을 아군 CC와 맞추기'
