> **한눈에 보기** — 첫 `Q` 뒤 강화 타이밍을 기다린다 · 벽과 상대를 한 선에 둔다 · 궁극기로 핵심 기술을 피한다

[[분류:탑]] [[분류:딜탱]]

## 첫 `Q`와 강화 `Q` 사이를 걸어서 채운다

**`정확성 프로토콜(Q)`은 첫 공격 뒤 잠시 기다려 다시 쓰면 두 번째 피해가 크게 늘어난다.**[* [딜탱 탑 카밀 공략](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=133520)] 첫 타격의 이동 속도로 상대 옆을 따라가고, 강화 표시가 오기 전에 두 번째 사용을 서두르지 않는다. 상대가 멀어질 수 있다면 미니언에 첫 `Q`를 준비해 강화 타격만 챔피언에게 전달한다.

## `W`는 바깥쪽으로 맞히고 안쪽으로 걸어간다

**`전술적 휩쓸기(W)`는 원뿔 바깥쪽의 적을 둔화하고 더 강하게 때리며 카밀을 회복시킨다.** 가까이 붙은 상대에게 바로 쓰기보다 한 걸음 물러나 바깥 선을 맞춘 뒤, 둔화 동안 다음 기본 공격 거리로 들어간다. 시전 중 움직일 수 있다는 점을 이용해 막타와 견제를 한 선에 둔다.

## 갈고리는 붙을 벽과 착지점을 함께 본다

**`갈고리 발사(E)`는 벽으로 이동한 뒤 다시 도약해 챔피언을 기절시킨다.**[* [스플릿 카밀 공략](https://lol.inven.co.kr/dataninfo/champion/manualToolView.php?idx=136992&vtype=pc)] 가까운 벽만 잡지 말고 두 번째 도약이 상대의 옆이나 뒤에 떨어지는지 본다. 상대의 밀치기나 이동 불가 효과가 남아 있으면 정면 진입을 늦추고, 도주에 쓸 벽도 기억한다.

## 궁극기는 가두기와 회피를 동시에 노린다

**`마법공학 최후통첩(R)`은 대상에게 도약해 일정 지역에 가두며 도약 순간 위치를 바꾼다.** 상대의 큰 기술이 날아오는 순간에 사용하면 피하면서 퇴로도 끊을 수 있다. 아군이 닿지 못하는 곳에 혼자 가두면 역으로 고립되므로, 착지 지점과 합류 시간을 먼저 확인한다.

## 커뮤니티에서 반복되는 실전 기준

카밀의 짧은 딜교는 첫 `Q`로 이속을 얻고 거리를 조절한 뒤, 강화되는 두 번째 `Q` 타이밍에 다시 붙는 흐름이다. 첫 타부터 모든 이동기를 쓰지 말고 상대 반격이 빠지는 시간을 기다려 두 번째 타의 고정 피해를 안전하게 넣는다.[* [MOBAFire 챌린저 카밀 가이드](https://www.mobafire.com/league-of-legends/build/styllees-challenger-camille-top-jng-540100)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W` 바깥쪽을 맞히면 둔화와 회복을 함께 얻지만 가까운 상대에게 무작정 쓰면 안쪽 피해만 들어간다. 상대가 달라붙을 때는 뒤로 빼며 바깥 날을 맞히거나, 반대로 몸 안쪽으로 파고들어 피할 상대에게 `E` 기절을 먼저 건다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

벽이 가까운 쪽에서 카밀은 `E` 발동이 빨라 갱호응과 킬각이 강해진다. 라인을 당길 때도 아무 위치가 아니라 사용할 벽과 정글 진입로가 함께 보이는 쪽에 서고, 벽이 먼 중앙에서는 `E`를 탈출용으로 아낀다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서 궁은 딜러를 가두는 용도뿐 아니라 핵심 스킬을 잠깐 피하는 무적 판정으로도 쓸 수 있다. 혼자 깊게 가두기 전에 아군이 따라올 거리인지 확인하고, 사이드에서는 궁으로 도주기를 끊어 확실한 1대1을 만든다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **카밀의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

