> **한눈에 보기** — 통의 마지막 체력을 먼저 친다 · `W`는 핵심 제어에 남긴다 · `R`은 합류보다 퇴로를 자른다

[[분류:탑]] [[분류:딜탱]]

## 화약통은 폭발보다 선점이 먼저다

**`화약통(E)`은 갱플랭크와 적 모두 공격할 수 있으므로 마지막 체력을 누가 먼저 치는지가 교환의 시작이다.**[* [갱플랭크 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=18)] 첫 통을 수풀이나 내 이동 경로 가까이에 두고, 상대가 막타를 노리러 들어올 때 기본 공격이나 `혀어어어업상(Q)`으로 터뜨린다. 연쇄 통은 상대 뒤가 아니라 첫 통이 안전하게 연결되는 범위부터 잡는다.

## `Q` 막타와 견제의 목적을 나눈다

**`Q`를 매번 챔피언에게 쓰면 안전한 막타와 통 제어에 쓸 기회를 함께 잃는다.** 상대가 통을 건드릴 수 없는 위치라면 미니언 막타로 성장하고, 상대가 통 사거리 안에 들어왔을 때만 `Q`를 교환에 묶는다. 웨이브가 밀리는 동안에는 통 하나를 퇴로에 남겨 추격을 끊는다.

## 귤은 첫 제어가 아니라 결정적인 제어에 쓴다

**`괴혈병 치료(W)`는 군중 제어를 제거하므로 짧은 둔화보다 후속 속박이나 제압 직전까지 아낄 가치가 크다.** 체력이 조금 빠졌다는 이유로 먼저 사용하면 다음 진입을 끊을 수 없다. 상대의 핵심 제어가 빠진 뒤에는 회복용으로 전환해 라인에 더 오래 남는다.

## 포탄은 싸움 한가운데보다 출구에 깐다

**`포탄 세례(R)`는 전장을 가로질러 쓸 수 있지만 이미 맞붙은 중앙보다 적이 빠질 통로를 덮을 때 오래 맞힌다.** 아군 제어가 시작되는 순간 뒤쪽에 깔아 퇴로를 좁히고, 내 라인에서 통 압박을 이어 갈 수 있는지도 함께 본다. 단순 지원 피해보다 적의 이동 선택을 줄이는 것이 먼저다.

## 커뮤니티에서 반복되는 실전 기준

갱플랭크의 라인전은 통을 많이 까는 것보다 마지막 체력 한 칸을 누가 먼저 치는지 관리하는 게임이다. 평타로 터뜨릴지 `Q`로 터뜨릴지 미리 정하고, 상대가 통 막타를 보러 들어오는 순간 패시브 평타까지 연결한다.[* [MOBAFire 갱플랭크 매치업 가이드](https://www.mobafire.com/league-of-legends/build/new-gp-build-guide-top-updated-all-matchups-650003)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W` 귤은 체력이 조금 빠졌다고 바로 먹으면 상대의 다음 확정 CC에 답이 없어진다. 위험한 기절이나 제압을 지우는 용도로 우선 남기고, 상대 핵심 제어가 빠진 것을 확인했을 때만 라인 유지용 회복으로 쓴다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

통을 웨이브 한가운데 계속 터뜨리면 선푸시는 되지만 갱플랭크가 안전하게 설 통이 사라진다. 수풀이나 내 뒤쪽에 예비 통을 하나 남기고, 큰 웨이브를 박을 때만 연쇄 폭발로 원거리 미니언까지 정리한다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 눈앞의 한 명을 맞히는 2연통보다 시야 밖에서 딜러와 퇴로를 함께 덮는 연쇄가 가치가 크다. 궁은 이미 싸우는 중앙보다 적이 빠질 길이나 아군 진입 뒤쪽에 깔아 통을 맞힐 시간을 만든다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **갱플랭크의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

