[[분류:탑]] [[분류:딜탱]]

## 한쪽에 서서 같은 다리만 쓰지 않는다

**우르곳의 기본 지속 효과는 적을 향한 다리마다 따로 산탄을 발사하므로 대상 주위를 돌아야 화력이 이어진다.**[* [우르곳 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=70)] 첫 산탄 뒤 곧장 반대편으로 가려 하지 말고, `부식성 폭약(Q)` 둔화나 `경멸(E)`로 위치를 바꿀 시간을 만든다. 준비되지 않은 다리 쪽으로 몸을 돌리면 짧은 교환에서도 확실한 피해를 남긴다.

## 표식이 생긴 뒤 심판의 원을 연다

**`심판의 원(W)`은 최근 다른 기술을 맞힌 챔피언을 우선하므로 먼저 `Q`나 `E`를 적중시켜야 한다.** 표식 없이 미니언 사이에서 켜면 원하는 대상을 때리지 못하고 이동 속도만 잃는다. 상대가 웨이브에서 떨어지는 순간 표식을 묻혀 산탄과 연속 사격을 한 대상에 모은다.

## `E`는 현재 위치보다 한 걸음 뒤를 노린다

**`경멸(E)`은 준비 동작 뒤 돌진해 충돌한 챔피언을 뒤로 넘긴다.** 상대의 현재 발밑보다 퇴로 쪽으로 몸을 맞추고, 보호막으로 첫 반격을 받아낸다. 빗나가면 탈출 수단도 함께 사라지므로 시야가 없거나 여러 명이 기다릴 수 있는 방향으로는 먼저 쓰지 않는다.

## 처형 표식 뒤에는 당기는 공간을 확보한다

**`불사의 공포(R)`는 맞힌 대상을 체력 기준 아래에서 끌어와 처형한다.** 섬광탄만 맞히고 벽이나 적진 깊숙이 들어가면 재사용할 자리가 없다. 표식이 박힌 뒤에는 산탄을 더 터뜨리되, 처형이 열리는 순간 방해받지 않을 거리를 남긴다.

## 커뮤니티에서 반복되는 실전 기준

우르곳의 딜교는 한 방향에서 오래 때리는 것보다 상대 주변을 돌며 다리 패시브를 차례로 터뜨릴 때 강하다. `E`로 뒤집은 뒤 `W`를 켜고 원을 그리되, 이미 터진 방향에 머물지 말고 다음 산탄이 남은 쪽으로 이동한다.[* [MOBAFire 우르곳 전 매치업 가이드](https://www.mobafire.com/league-of-legends/build/goliathgames-ultimate-guide-to-urgot-tips-on-every-matchup-8m-mastery-554383)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W`는 최근 다른 스킬을 맞힌 챔피언을 우선하므로 `Q`나 `E` 표식 없이 켜면 미니언에 탄이 새기 쉽다. 라인전에서는 먼저 표식을 묻히고 켜며, 포탑을 칠 때는 평타와 `W`를 끊어 쓰는 리듬으로 손해를 줄인다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

다리 패시브로 미니언을 치면 생각보다 라인이 빨리 밀린다. 상대를 견제하려고 방향을 바꿀 때 원거리 미니언까지 같이 터뜨리지 않도록 서는 각을 조절하고, `E`가 없는 동안은 깊은 선푸시를 피한다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

