[[분류:탑]] [[분류:딜탱]]

## 교환 전에 무덤 수부터 만든다

**`최후의 의식(Q)`으로 대상을 처치하면 무덤이 생기고, 무덤이 있어야 안개 망령을 한꺼번에 깨울 수 있다.**[* [요릭 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=81)] 아무 준비 없이 `애도의 안개(E)`만 맞혀도 압박이 짧다. 웨이브 막타로 무덤을 모으고 상대가 앞으로 나오는 순간 망령을 일으켜 `E` 표식과 함께 보낸다.

## 벽은 가두기보다 이동기를 확인하는 데 쓴다

**`망자의 진(W)`은 공격해 부술 수 있는 벽이라 상대의 이동기가 남아 있으면 즉시 빠져나간다.** 먼저 `E` 둔화와 망령으로 걸음을 재촉하게 하고, 이동기가 빠진 뒤 퇴로에 벽을 세운다. 벽 안에서 공격만 하기보다 상대가 어느 칸을 먼저 치는지 보고 몸으로 출구를 막는다.

## 망령과 직접 공격의 시간을 겹친다

**표식이 있는 대상으로 소환물이 빠르게 접근하므로 요릭도 같은 순간에 들어가야 피해가 분산되지 않는다.** 너무 먼저 걸으면 상대가 요릭만 때리고, 너무 늦으면 망령이 정리된다. 망령이 첫 공격을 시작할 때 `Q` 강화 공격을 맞히고 짧게 물러난다.

## 안개 마녀가 만든 웨이브를 기준으로 움직인다

**`군도의 장송곡(R)`의 안개 마녀는 쓰러진 적을 망령으로 일으켜 지속 압박을 만든다.** 마녀와 반대쪽으로 무리하게 이동하기보다 밀리는 라인을 먼저 깊게 보내고 시야를 확보한다. 마녀가 집중 공격을 받으면 챔피언을 쫓기보다 살려서 다음 웨이브까지 연결한다.

## 커뮤니티에서 반복되는 실전 기준

요릭은 무덤과 안개 망령이 준비되지 않은 상태에서 챔피언에게 `E`만 맞혀도 압박이 이어지지 않는다. `Q`로 무덤을 쌓고 최소한의 망령 수를 준비한 뒤 `E`를 던져야 상대가 막타와 회피를 동시에 처리하게 된다.[* [MOBAFire 요릭 운영 가이드](https://www.mobafire.com/league-of-legends/build/14-17-how-to-win-with-yorick-635126)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W` 벽은 상대를 가두는 용도 외에도 내 퇴로를 자르는 추격자를 잠깐 막는 데 쓸 수 있다. 돌진으로 벽을 넘는 챔피언에게는 먼저 쓰지 말고 이동기가 빠진 뒤 가두며, 평타가 빠른 상대에게는 벽이 금방 깨진다는 점을 계산한다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

라인을 밀 때 본체, 망령, 안개 마녀가 한 웨이브에 전부 붙으면 속도는 빠르지만 갱을 피할 자원이 없다. 적 위치가 안 보이면 마녀가 밀게 두고 요릭은 뒤에서 거리를 잡거나, 다음 웨이브 합류 지점을 보고 천천히 전진한다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

사이드 운영은 포탑만 치는 일이 아니라 상대 몇 명을 부를지 계산하는 일이다. 두 명 이상이 보이면 바로 빠져 아군이 반대편을 챙길 시간을 만들고, 한타 합류가 필요하면 마녀를 다른 라인에 풀어 압박을 남긴다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **요릭의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- 무덤과 망령 수 확인 뒤 `E` 쓰기
- 상대 이동기가 빠진 뒤 `W` 가두기
- 마녀 체력을 공짜로 내주지 않기
- 시야 없을 때 본체와 소환물을 함께 깊게 넣지 않기
