> **한눈에 보기** — `Q`를 한 대상에게 맞힌다 · 보호막은 큰 피해 뒤에 쓴다 · `R`로 전투의 핵심 한 명을 분리한다

[[분류:탑]] [[분류:딜탱]]

## 말살은 미니언 밖에서 맞힌다

**`말살(Q)`은 한 대상만 맞힐 때 피해가 커지므로 상대와 미니언을 한 범위에 넣지 않는 각도가 중요하다.**[* [모데카이저 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=41)] `죽음의 손아귀(E)`로 상대를 웨이브 옆으로 끌어낸 뒤 철퇴 중심을 맞힌다. 막타와 견제를 동시에 노리다가 여러 대상을 치면 가장 강한 단일 타격을 잃는다.

## 지속 효과 세 번째 적중을 계획한다

**기본 공격과 기본 기술을 세 번 맞혀야 주변 피해와 이동 속도가 켜진다.** 첫 두 번을 쓰고 상대가 빠질 수 있다면 무리하게 쫓지 말고, `E`가 적중할 때 세 번째 타격이 이어지도록 순서를 바꾼다. 지속 효과가 켜진 뒤에는 상대 옆을 따라 걸으며 기본 공격 간격을 유지한다.

## 보호막 충전량을 보고 두 번째 사용을 고른다

**`불멸(W)`은 주고받은 피해로 충전한 값을 보호막으로 바꾸고 다시 사용하면 회복한다.** 교환 시작과 동시에 누르면 작은 보호막만 생긴다. 큰 피해를 받은 직후 보호막으로 다음 타격을 막고, 전투가 끝났을 때 남은 값을 회복으로 바꾼다.

## 죽음의 세계에서 얻을 승리를 먼저 계산한다

**`죽음의 세계(R)`는 대상 하나를 분리하고 능력치 일부를 훔치지만, 들어간 뒤에는 외부 도움을 기대할 수 없다.** 이동기가 빠진 핵심 적이나 아군을 방해하는 앞선 적을 고른다. 단순히 체력이 낮은 대상보다 제한된 공간에서 `Q`와 `E`를 맞힐 수 있는 대상을 데려간다.

## 커뮤니티에서 반복되는 실전 기준

모데카이저는 `E`로 끌고 `Q`를 맞힌 뒤 패시브를 켜는 정직한 흐름이 강하다. `E`를 먼저 던질 때 상대 이동기가 남아 있다면 `Q`까지 빗나갈 수 있으므로, 걸어서 압박해 무빙을 제한하거나 미니언 막타 순간을 노린다.[* [MOBAFire 모데카이저 매치업 가이드](https://www.mobafire.com/league-of-legends/build/patch-13-21-my-mordekaisers-build-top-jungle-mid-matchups-616062)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W` 보호막은 받은 피해와 준 피해로 차기 때문에 싸움이 끝난 뒤 비어 있는 상태와 꽉 찬 상태의 힘 차이가 크다. 체력이 조금 빠졌다고 바로 회복으로 바꾸기보다 다음 맞딜에서 큰 보호막으로 쓸지, 라인 유지용 체력으로 바꿀지 결정한다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

`Q`를 단일 대상에게 맞히면 피해가 강해지므로 미니언과 챔피언을 같이 치는 것보다 옆각에서 챔피언만 맞히는 구도가 좋다. 반대로 선푸시가 목적이면 미니언 전체를 긁되 `E`까지 웨이브에 써 갱 회피 수단을 잃지 않는다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 가장 센 적을 무조건 궁으로 데려가기보다, 아군 진형을 무너뜨리는 핵심 진입자를 격리하거나 보호기가 없는 딜러를 잡는 선택이 좋다. 죽음의 세계에서 못 잡더라도 바깥 전투가 이길 시간을 벌 수 있는지 본다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **모데카이저의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- `E` 전에 상대 이동기 확인하기
- `Q` 단일 적중 각 만들기
- `W`를 보호막과 회복 중 어디에 쓸지 정하기
- 웨이브에 `E`까지 쓰지 않기
