[[분류:탑]] [[분류:딜탱]]

## 덫을 맞힌 뒤 거리를 직접 지킨다

**`덫날리기(Q)`는 적에게 꽂힌 뒤 가까운 거리를 유지해야 추가 피해와 끌어당김이 발생한다.**[* [클레드 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=132)] 적중만 확인하고 멈추지 말고 상대의 퇴로를 따라 비스듬히 걸어 밧줄을 유지한다. 상대 이동기가 남았으면 `이랴!(E)`를 먼저 쓰지 않고 밧줄이 끊기려는 순간 따라간다.

## 버럭버럭의 네 타를 낭비하지 않는다

**`버럭버럭(W)`은 다음 네 번의 기본 공격을 빠르게 만들고 네 번째 공격을 강화한다.** 자동으로 발동하는 구간에 미니언을 치면 가장 강한 타격을 교환 전에 잃는다. 활성 가능 시간을 보고 막타를 잠시 미루고, `Q`로 붙잡은 챔피언에게 네 타를 연결한다.

## 내렸을 때는 도망만 가지 않는다

**스칼 미탑승 상태의 `빵야!(Q)`와 챔피언 공격은 용기를 회복하고, 다시 탑승하면 전투를 뒤집을 체력이 생긴다.** 무조건 포탑으로만 달리면 용기를 채울 기회가 없다. 상대 핵심 기술이 빠졌을 때 사거리를 유지하며 `Q`와 기본 공격으로 마지막 용기를 채우고, 재탑승 직후 다시 거리를 좁힌다.

## 궁극기 경로를 아군 진입선으로 만든다

**`돌겨어어억!!!(R)`은 목표 지점으로 달리며 경로의 아군을 가속하고 첫 적 챔피언에게 돌진한다.** 적 한 명만 쫓는 직선보다 아군이 함께 들어올 수 있는 길을 고른다. 도착 지점 뒤에 적 포탑이나 막힌 지형이 없는지 보고, 보호막이 남아 있을 때 첫 제어를 받아낸다.

## 커뮤니티에서 반복되는 실전 기준

클레드는 `W`가 켜지는 순간을 직접 선택하기 어렵기 때문에 준비되지 않은 평타로 발동시키지 않는 관리가 중요하다. 상대와 싸울 생각이면 막타를 스킬로 먹어 `W`를 아끼고, 네 번째 강화 평타까지 붙을 수 있는 거리에서 교환을 시작한다.[* [MOBAFire 클레드 탑 가이드](https://www.mobafire.com/league-of-legends/build/the-holy-scripts-of-kled-toplane-650760)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`Q` 사슬은 맞힌 뒤 일정 거리를 유지해야 두 번째 피해와 당기기가 들어간다. 상대가 앞으로 파고들면 뒤로, 도망가면 `E`로 따라가며 사슬 범위를 유지하고, 끊길 것 같다면 무리한 추격보다 빠지는 쪽을 택한다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

스칼에서 내렸을 때는 약해 보이지만 챔피언과 미니언을 때려 용기를 채우면 체력을 크게 되찾고 재탑승한다. 웨이브가 많을 때는 무조건 귀환하지 말고 `Q` 산탄과 빠른 평타로 재탑승 각을 보되, 상대 확정 폭딜이 남았으면 욕심을 버린다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

궁은 먼 거리 진입뿐 아니라 아군에게 이동 속도 길을 열고 첫 대상에게 붙는 수단이다. 혼자 먼저 박히는 경로보다 아군이 따라올 직선 길을 고르고, 사이드에서는 상대가 벽을 세우거나 도주기를 쓴 뒤 재진입용으로 활용한다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **클레드의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

