> **한눈에 보기** — `E` 번개를 먼저 예약한다 · `Q` 기절로 폭발 안에 묶는다 · 두 번째 `W`까지 같은 대상을 놓치지 않는다

[[분류:탑]] [[분류:딜탱]]

## 번개가 떨어질 자리에 먼저 달려든다

**`천공 분열(E)`은 잠시 뒤 지정 위치에 떨어지고 볼리베어가 범위 안에 있으면 보호막을 준다.**[* [볼리베어 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=88)] 상대 발밑에 바로 쓰기보다 퇴로 쪽에 예약하고 `번개 강타(Q)`로 밀어 넣는다. 폭발과 기절이 겹치면 피해와 보호막을 함께 챙겨 반격까지 받아낼 수 있다.

## 첫 상처는 다음 교환의 약속이다

**`광란의 상처(W)`는 표식이 남은 대상에게 다시 쓰면 피해와 회복이 커진다.** 첫 사용 뒤 무조건 추격하기보다 표식이 유지되는 거리에서 다음 재사용을 기다린다. 상대가 완전히 빠질 수 있다면 짧은 이득으로 끝내고, 이동기가 빠졌다면 두 번째 `W`까지 압박을 이어 간다.

## `Q`는 접근과 퇴로 중 하나에 쓴다

**`번개 강타(Q)`는 적을 향할 때 빨라지고 첫 기본 공격을 기절로 바꾼다.** 매번 진입에 쓰면 갱킹이나 역추격에서 벗어날 수 없다. `E`가 적중할 확률이 높은 때만 먼저 달려들고, 시야가 없을 때는 기절을 들고 웨이브를 짧게 정리한다.

## 궁극기 착지 뒤 목표를 미리 정한다

**`폭풍을 부르는 자(R)`는 도약 지점에 피해와 둔화를 주고 근처 포탑을 잠시 비활성화한다.** 포탑만 끈다는 이유로 깊게 뛰지 말고, 착지 직후 두 번째 `W`를 넣을 대상과 빠질 방향을 먼저 정한다. 적이 흩어지면 체력이 낮은 한 명보다 아군과 같은 방향의 대상을 고른다.

## 커뮤니티에서 반복되는 실전 기준

볼리베어의 짧은 교환은 `E` 번개를 먼저 깔고 `Q` 기절로 그 안에 상대를 묶는 흐름이 안정적이다. 번개가 떨어지기 전에 상대가 범위를 벗어날 것 같으면 끝까지 쫓지 말고 보호막만 챙겨 다음 교환을 준비한다.[* [MOBAFire 챌린저 볼리베어 탑 가이드](https://www.mobafire.com/league-of-legends/build/26-17-challenger-volibear-top-guide-609641)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W`는 같은 대상을 두 번 물어야 두 번째 피해와 회복이 강해진다. 첫 표식을 묻힌 뒤 상대가 완전히 빠질 수 있는 상황이면 긴 맞딜을 억지로 열지 말고, 스킬쿨이 돌아올 때까지 웨이브와 거리를 조절해 재접근한다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

패시브 연쇄 번개는 선푸시를 쉽게 만들지만 원하지 않아도 미니언 체력을 깎는다. 라인을 당기고 싶다면 평타 횟수를 줄이고 막타만 먹으며, 포탑 압박이나 다이브를 준비할 때만 패시브를 미리 쌓아 속도를 낸다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

중반에는 궁으로 포탑을 끄는 다이브와 사이드 1대1이 강하지만, 후반 정면 한타에서는 쉽게 카이팅당한다. 진입 전에 `Q`로 닿을 대상과 궁 착지 지점을 정하고, 못 닿으면 아군 딜러 앞에서 진입자를 물어 주는 쪽으로 전환한다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **볼리베어의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- `E`를 먼저 깔고 `Q`로 묶기
- 첫 `W` 표식 뒤 두 번째 물기 거리 계산하기
- 패시브 선푸시를 필요할 때만 켜기
- 궁 다이브 전에 아군 후속 거리 보기
