## 분노가 찬 웨이브에서 앞으로 선다

**트린다미어는 분노가 쌓일수록 치명타 압박이 커지고 `피의 갈망(Q)`으로 회복할 수도 있다.**[* [트린다미어 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=66)] 분노가 낮을 때 억지로 싸우기보다 미니언을 공격해 자원을 만든 뒤 상대의 막타에 맞춰 접근한다. 회복에 분노를 쓰면 다음 교환의 위력이 줄어드니 라인 유지와 압박 중 하나를 분명히 고른다.

## 외침은 상대의 등을 확인하고 쓴다

**`조롱의 외침(W)`은 주변 적의 공격력을 낮추고 등을 돌린 대상은 추가로 둔화한다.** 상대가 이미 도망치는 순간에 쓰면 추격이 길어지고, 서로 마주 본 채 싸울 때도 공격력 감소로 맞교환을 유리하게 만든다. 사거리 밖에서 미리 누르지 않고 아이콘이 활성화되는 거리까지 기다린다.

## 회전 베기는 진입보다 재배치에 남긴다

**`회전 베기(E)`는 경로를 가르며 이동하므로 벽을 넘거나 상대 퇴로를 선점할 수 있다.** 첫 접근에 전부 쓰면 군중 제어를 맞은 뒤 빠질 수 없다. 걸어서 닿을 수 있는 상대에게는 기본 공격부터 시작하고, 거리가 벌어지거나 위험한 기술을 피할 때 회전한다.

## 불사가 끝나는 순간을 먼저 설계한다

**`불사의 분노(R)`는 잠시 체력이 일정 수치 아래로 내려가지 않게 하지만 끝난 뒤의 안전까지 보장하지 않는다.** 마지막까지 공격만 하기보다 종료 전에 `E`로 나갈 방향을 확보한다. 상대 핵심 제어가 남아 있다면 더 일찍 궁극기를 사용해 행동 불가 상태에서 쓰지 못하는 실수를 줄인다.

## 커뮤니티에서 반복되는 실전 기준

트린다미어는 분노가 가득 찼을 때 치명타 기대값과 회복 선택지가 함께 생긴다. 싸움 직전 미니언으로 분노를 채우되, 체력이 조금 빠졌다고 바로 `Q` 회복으로 전부 써 버리면 다음 맞딜 압박이 크게 줄어든다.[* [MOBAFire 트린다미어 팁 가이드](https://www.mobafire.com/league-of-legends/build/raens-tryndamere-tips-amp-build-569493)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`E` 회전 베기는 진입과 이탈을 모두 맡으므로 첫 접근에 쓰면 상대 이동기 뒤를 따라갈 수 없다. 걸어서 붙을 수 있는 상대에게는 평타와 `W` 둔화로 시작하고, 도주기를 본 뒤 `E`로 따라가는 편이 킬각을 오래 유지한다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

사이드에서 웨이브를 빨리 밀 수 있지만 정글 위치가 안 보일 때 포탑만 치면 궁과 회전을 모두 빼고도 잡힐 수 있다. 다음 웨이브가 오는 시간과 적 숫자를 확인하고, 궁이 없을 때는 한 줄 더 먹는 욕심을 줄인다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 궁으로 오래 버티는 것보다 궁이 끝난 뒤 빠질 경로가 있는지가 중요하다. 정면 진입보다 측면에서 딜러에게 붙고, 마지막 체력 구간에는 처형 피해와 점화를 예상해 너무 늦게 누르지 않는다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **트린다미어의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

