한타에서는 궁으로 오래 버티는 것보다 궁이 끝난 뒤 빠질 경로가 있는지가 중요하다. 정면 진입보다 측면에서 딜러에게 붙고, 마지막 체력 구간에는 처형 피해와 점화를 예상해 너무 늦게 누르지 않는다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

