## 기술과 이동 명령을 한 동작으로 묶는다

**암베사는 기술 사용 중 기본 공격이나 이동 명령을 내리면 끝난 뒤 그 방향으로 돌진한다.**[* [암베사 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=169)] 피해만 보고 기술을 연속 사용하면 원치 않는 방향으로 들어가거나 돌진을 잃는다. 한 번 쓸 때마다 다음 위치를 먼저 찍고, 상대의 옆을 지나 퇴로를 막을지 뒤로 빠질지 정한다.

## 강화 공격으로 기력 순환을 잇는다

**돌진이 개시될 때 쌓이는 충전은 다음 기본 공격의 사거리와 속도를 높이고 적중하면 기력을 회복한다.** 기술만 빠르게 누르면 기력이 먼저 바닥난다. 돌진 뒤 강화 공격을 한 번씩 섞고, 상대가 사거리 밖으로 빠지면 미니언에 쓸지 추격을 멈출지 즉시 고른다.

## 첫 `Q`와 두 번째 `Q`의 선을 바꾼다

**`교활한 휩쓸기(Q)`는 반원의 날에 맞히면 강하고, 적중 뒤의 `파멸의 일격(Q)`은 일직선 첫 대상에게 추가 피해를 준다.** 첫 타는 옆으로 돌진해 바깥 날을 맞히고, 두 번째는 미니언에 막히지 않는 선을 만든다. 같은 자리에서 두 번 쓰면 상대가 한 방향으로 모두 피하기 쉽다.

## 방패와 궁극기는 반격을 읽고 쓴다

**`배척(W)`은 준비 중 챔피언 피해를 막으면 반격 피해가 커지고, `공개 처형(R)`은 선상 가장 먼 챔피언을 제압한다.** 상대 핵심 공격 직전에 `W`로 받아내고, 도주기가 빠진 뒤 궁극기로 뒤를 잡는다. 여러 명이 한 선에 있으면 원하지 않는 후방 대상을 잡지 않도록 각도를 좁힌다.

## 커뮤니티에서 반복되는 실전 기준

암베사는 스킬 뒤 이동 명령으로 패시브 돌진 방향을 정하는 챔피언이라, 버튼을 빨리 누르는 것보다 다음 착지점을 고르는 것이 중요하다. 상대 뒤로 넘어갈지 옆으로 비킬지 먼저 정하고 스킬을 써야 기력 회복과 강화 평타를 놓치지 않는다.[* [MOBAFire 암베사 심화 가이드](https://www.mobafire.com/league-of-legends/build/25-13-in-depth-guide-for-top-amp-jg-ambessa-ambessa-build-lol-extra-details-for-all-items-listed-643789)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`W`는 보호막으로 피해를 받아 내는 동안 챔피언 피해를 막으면 반격 피해도 강해진다. 상대 큰 스킬 모션에 맞춰 쓰고, 보호막만 얻으려고 미리 누르기보다 `Q`나 `E` 후 돌진과 묶어 중앙을 맞힌다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

스킬과 돌진을 반복하면 웨이브를 쉽게 긁지만 기력이 비면 다음 교환에서 아무것도 할 수 없다. 선푸시할 때 모든 스킬을 쓰지 말고 강화 평타로 기력을 돌려받으며, 최소 한 번의 돌진은 갱 회피 방향으로 남긴다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 궁으로 가장 멀리 있는 챔피언에게 가므로 직선 위 대상 배치를 확인해야 한다. 원한 대상 뒤에 더 먼 챔피언이 있으면 궁이 빗나갈 수 있고, 들어간 뒤에는 짧은 돌진을 좌우로 섞어 CC 방향을 흘린다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **암베사의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

## 게임 전에 확인할 체크리스트

- 스킬 전 패시브 돌진 방향 정하기
- 강화 평타로 기력 회수하기
- `W`를 상대 큰 피해에 맞추기
- 웨이브에 기력을 전부 쓰지 않기
