[[분류:탑]] [[분류:딜탱]]

## 부메랑을 받는 자리까지 설계한다

**미니 나르의 `부메랑 던지기(Q)`는 돌아오는 부메랑을 받으면 재사용 대기시간이 줄어든다.**[* [나르 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=120)] 맞히는 선만 보지 말고 다음에 서고 싶은 위치로 몸을 움직여 회수한다. 상대 퇴로 쪽에서 받으면 `슝슝(W)` 세 번째 타격을 이어 가고, 위험하면 뒤쪽으로 유도해 교환을 끝낸다.

## 세 번째 타격 뒤 이동 속도로 빠진다

**미니 나르는 기본 공격과 기술의 세 번째 적중으로 추가 피해와 이동 속도를 얻는다.** 첫 표식부터 오래 붙기보다 막타와 `Q`로 두 번을 준비하고, 상대가 앞으로 올 때 세 번째를 터뜨린 뒤 거리를 벌린다. 몸이 약한 상태에서 이동 속도가 끝난 뒤까지 싸움을 늘리지 않는다.

## 분노가 가득 차기 전에 착지점을 고른다

**`폴짝(E)`은 유닛 위에 착지하면 한 번 더 튀므로 변신 진입 거리를 크게 바꿀 수 있다.** 분노가 거의 찼을 때 앞 미니언을 발판으로 삼아 적 뒤나 옆에 착지한다. 단순히 정면으로 뛰면 상대가 벽에서 멀어져 메가 나르의 제어를 피하기 쉽다.

## 메가 나르의 제어를 벽과 묶는다

**메가 나르의 `나르!(R)`는 적을 밀치고 벽에 부딪히면 기절과 추가 피해를 준다.** 변신하자마자 쓰기보다 `우지끈(E)`이나 `쿵쾅(W)`으로 벽 쪽 이동을 강요한다. 궁극기 뒤 돌덩이를 주워 `Q` 재사용을 당기고, 변신이 끝나기 전에 빠질 길을 남긴다.

## 커뮤니티에서 반복되는 실전 기준

미니 나르는 사거리와 `W` 3타 이속으로 짤교를 누적하고, 메가 나르는 CC 연계로 한 번에 크게 싸운다. 분노가 애매할 때 억지로 들어가기보다 곧 변신할 웨이브와 벽 위치를 계산해 두 형태의 역할을 분리한다.[* [MOBAFire 다이아 나르 가이드](https://www.mobafire.com/league-of-legends/build/26-16-diamond-gnar-guide-thing-in-the-ice-546377)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`Q` 부메랑이나 돌을 다시 받으면 스킬쿨이 줄어드므로 던진 뒤 돌아오는 경로까지 움직임에 포함해야 한다. 상대를 맞히고도 무기를 못 받으면 다음 견제 주기가 길어지니, 킬각이 아니라면 회수 가능한 각으로 던진다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

미니 나르 상태에서 평타 견제를 계속하면 라인이 밀리고 몸이 약한 상태로 깊어질 수 있다. 분노가 낮고 정글이 안 보이면 막타 위주로 줄이고, 메가 변신이 가까울 때 큰 웨이브를 박아 다이브나 귀환 선택을 만든다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 분노가 가득 찬 뒤 순간적으로 진입할 벽과 적 진형이 필요하다. 너무 일찍 메가가 되어 시간을 보내지 말고 미니언이나 정글 몬스터로 분노를 맞추며, `E` 점프로 변신해 궁 벽꿍까지 이어 갈 각을 찾는다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **나르의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

