**`라그나로크(R)`는 방해 효과를 정화하고 면역을 주며, 기본 공격이나 `E`로 챔피언을 맞히면 지속시간이 늘어난다.** 너무 일찍 켜고 걸어가며 시간을 버리지 말고 핵심 제어가 들어온 순간 해제한다. 활성 중에는 가장 가까운 적을 계속 적중해 면역 시간을 유지한다.

## 커뮤니티에서 반복되는 실전 기준

올라프의 추격은 첫 `Q`를 맞히는 것보다 떨어진 도끼를 계속 줍는 동선이 중요하다. 상대 뒤쪽이 아니라 옆이나 퇴로 쪽에 던져 주우며 따라갈 수 있게 만들고, 도끼가 너무 멀리 떨어지면 다음 스킬쿨이 비어 킬각이 끊긴다.[* [MOBAFire 챌린저 올라프 탑 가이드](https://www.mobafire.com/league-of-legends/build/26-17-challenger-olaf-top-guide-632382)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

체력이 낮을수록 공속이 오르지만 언제나 끝까지 맞딜하라는 뜻은 아니다. `W` 보호막과 `E` 고정 피해가 남았는지 확인하고, 상대가 거리를 벌릴 수 있다면 낮은 체력을 미끼로 쓰기보다 도끼 둔화를 먼저 맞힌다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

도끼를 주우며 웨이브를 반복해서 긁으면 선푸시는 빠르지만 정글에게 길게 노출된다. 라인을 밀 목적이 아니면 챔피언만 맞는 옆각으로 던지고, 깊게 들어갈 때는 도끼 회수 경로가 내 진영 쪽으로 이어지게 한다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 궁을 켠 뒤 공격을 이어 가야 CC 면역 시간이 유지된다. 닿기 어려운 대상을 무조건 쫓기보다 도끼를 맞힐 수 있는 앞라인을 때리며 지속시간을 유지하고, 길이 열린 순간 딜러로 방향을 바꾼다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **올라프의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

