> **한눈에 보기** — 촉수가 있는 구역에서 싸운다 · `E` 영혼을 먼저 뽑는다 · `R` 뒤에는 이동보다 `W` 적중을 반복한다

[[분류:탑]] [[분류:딜탱]]

## 촉수 사이에 전투 구역을 만든다

**일라오이의 촉수는 공격할 때 피해와 회복을 함께 만들므로 벽 근처의 배치가 교환의 기반이다.**[* [일라오이 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=128)] 촉수 하나만 있는 곳에서 억지로 싸우기보다 웨이브가 오는 길에 여러 촉수가 닿는 구역을 만든다. 상대가 촉수를 지우러 다가오면 `영혼의 시험(E)` 투사체가 미니언에 막히지 않는 각도를 잡는다.

## 영혼을 뽑은 뒤 본체와 겹쳐 때린다

**`영혼의 시험(E)`은 분리한 영혼이 받은 피해 일부를 원래 대상에게 전달한다.** 영혼만 바라보고 서 있기보다 상대 본체가 함께 맞는 위치에서 `촉수 강타(Q)`와 촉수 공격을 겹친다. 대상이 범위를 벗어나면 숙주가 되어 촉수를 피해야 하므로 무리한 추격 없이 라인 주도권을 얻는다.

## `W`로 원하는 촉수의 공격을 부른다

**`혹독한 가르침(W)`은 대상에게 도약하고 근처 촉수도 같은 대상을 공격하게 한다.** 촉수가 없는 곳에서 단순 접근기로 쓰면 반격을 그대로 맞는다. 영혼이나 챔피언이 여러 촉수 범위에 겹친 순간에 사용하고, 후려치기 선을 피하려는 방향을 보고 다음 `Q`를 겨눈다.

## 궁극기 뒤에는 생성된 촉수를 믿고 버틴다

**`믿음의 도약(R)`은 맞힌 챔피언 수만큼 촉수를 만들고 잠시 `W` 재사용을 크게 줄인다.** 여러 명이 들어온 순간 중앙에서 사용한 뒤 한 대상에게 `W`를 반복해 촉수 공격과 회복을 이어 간다. 궁극기 직후 바깥으로 걸어 나가면 새 촉수의 범위를 스스로 버리게 된다.

## 커뮤니티에서 반복되는 실전 기준

일라오이는 촉수가 없는 넓은 곳에서 싸우면 `E` 영혼을 맞혀도 후속 압박이 약하다. 라인을 밀기 전에 벽 촉수 위치를 만들고, 상대가 막타를 칠 때 촉수와 일라오이 사이로 오도록 유도해 영혼과 본체를 함께 때린다.[* [MOBAFire 일라오이 원챔 심화 가이드](https://www.mobafire.com/league-of-legends/build/26-15-illaoi-otp-advanced-guide-618052)] 교환을 열기 전에는 상대 핵심기와 내 퇴로를 함께 보고, 한 번 이득을 봤다면 다음 스킬쿨까지 욕심을 줄인다. 이 챔피언은 버튼을 전부 누르는 속도보다 유리한 구간만 반복하는 쪽이 훨씬 안정적이다.

## 스킬쿨이 비는 순간을 관리한다

`E`가 빗나간 직후는 일라오이가 가장 약한 시간이다. 무리하게 `Q`나 `W`로 계속 싸우지 말고 한 발 빠져 다음 영혼의 시험을 기다리며, 맞혔다면 영혼을 칠지 본체를 압박할지 상대 이동에 따라 정한다. **딜교가 끝난 뒤 남은 스킬이 없으면 미니언 막타보다 안전거리 회복이 먼저다.** 상대가 되받아칠 핵심기가 돌아오기 전에 수풀이나 아군 미니언 뒤로 빠져 다음 교환을 다시 설계한다.

## 웨이브를 킬각과 연결한다

일라오이는 밀어 놓고 촉수 구역에서 상대 정글까지 받아치는 그림이 강하다. 궁이 없거나 촉수 수가 부족하면 같은 선푸시가 위험해지므로, 정글 위치와 궁 스킬쿨을 확인한 뒤 번개처럼 웨이브를 지울지 당길지 선택한다. **국내에서 흔히 말하는 "라인을 예쁘게 만든다"는 것은 막타를 더 먹는다는 뜻만이 아니다.** 상대가 CS를 먹으러 길게 나오게 만들고, 내 핵심기가 돌아오는 타이밍에 싸울 공간을 남기는 일이다.

## 사이드와 한타에서 역할을 바꾼다

한타에서는 적이 먼저 들어와 뭉쳤을 때 궁 가치가 높고, 내가 달려가서 시작하면 쉽게 흩어진다. 앞라인을 미끼로 적이 좁은 곳에 들어오게 만들고, 궁 뒤에는 화면의 촉수를 하나씩 조종하려 하기보다 `W`로 목표를 찍어 연속 강타를 유도한다. 라인전에서 잘 컸더라도 시야 없이 먼저 들어가면 CC와 집중 공격을 그대로 맞는다. 들어갈 대상, 빠질 방향, 아군 후속 거리 세 가지가 맞을 때만 길게 싸운다.

## 불리해졌을 때는 손해를 끊는다

라인전이 꼬였을 때는 킬을 되갚으려고 같은 자리에서 다시 싸우지 않는다. **일라오이의 핵심 스킬을 웨이브 정리에 전부 쓰지 말고, 상대가 다이브하거나 더 깊게 들어올 때 받아칠 한 세트를 남긴다.** 큰 웨이브를 안전하게 먹은 뒤 시야를 잡고, 혼자 복구하기 어렵다면 정글 교전보다 반대편 빈 라인과 아군 합류 타이밍을 먼저 챙긴다.

